const responseText = $input.first().json.body || $input.first().json.data || '';
const itemRegex = /<item>([\s\S]*?)<\/item>/gi;
const crashes = [];
let match;

while ((match = itemRegex.exec(responseText)) !== null) {
  const itemXml = match[1];
  const getTag = (tag) => {
    const m = new RegExp('<' + tag + '[^>]*>([\s\S]*?)</' + tag + '>', 'i').exec(itemXml);
    return m ? m[1].replace(/<!\[CDATA\[/g, '').replace(/\]\]>/g, '').trim() : '';
  };

  const title = getTag('title');
  const desc = getTag('description').replace(/<[^>]+>/g, '');
  const link = getTag('link');
  const pubDate = getTag('pubDate');

  const combined = (title + ' ' + desc).toLowerCase();
  if (['crash', 'accident', 'wreck', 'collision', 'multi-vehicle'].some(k => combined.includes(k))) {
    let location = 'Georgia, USA';
    if (combined.includes('i-75')) location = 'I-75, Georgia';
    else if (combined.includes('i-85')) location = 'I-85, Georgia';
    else if (combined.includes('i-285')) location = 'I-285 (Perimeter), Atlanta, GA';
    else if (combined.includes('i-95')) location = 'I-95, Georgia';
    else if (combined.includes('i-20')) location = 'I-20, Georgia';

    crashes.push({
      json: {
        incident_id: link || `crash_${Date.now()}`,
        title: title,
        location: location,
        description: desc,
        timestamp: pubDate,
        source: 'WSB-TV Atlanta Live Feed'
      }
    });
  }
}

return crashes.length > 0 ? crashes : [{ json: { status: 'No new crashes detected at this interval' } }];
